from pathlib import Path
import json,hashlib,re

root=Path.cwd()
home=Path.home()
prod=home/"prediction_research_prod"
bridge=home/".local/share/prediction-chat-bridge"
C8="DEV-PRED-CONT-NEXT-c8dcbf91be52fd2957116bd6"

def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()

def read_json(p):
    if not p.is_file() or p.is_symlink():
        return None
    try:
        o=json.loads(p.read_text(encoding="utf-8",errors="replace"))
        return o if isinstance(o,dict) else None
    except Exception:
        return None

# Prior executor state.
states={}
for tid in (
    "DEV-PRED-REQUESTED-REPAIRS-FINAL-ACCEPT-20261005",
    "DEV-PRED-REPAIRS-TARGETED-VERIFY-R2-20261005",
    C8,
):
    o=read_json(home/".local/state/prediction-project-executor"/(tid+".json")) or {}
    states[tid]={
        "status":o.get("status","MISSING"),
        "source_commit":o.get("source_commit"),
        "operation_count":o.get("operation_count"),
    }

# Recover compact c8 wake payload if present.
c8_line=None
c8_queue=None
for q in ("sent","inflight","outbox"):
    d=bridge/q
    if not d.is_dir():
        continue
    for p in d.glob("*.json"):
        o=read_json(p) or {}
        if str(o.get("task_id") or "")!=C8:
            continue
        msg=str(o.get("message") or "")
        m=re.search(r"REPAIR_ACCEPTANCE\s+(\{[^\n]+\})",msg)
        if m:
            c8_line=m.group(1)
            c8_queue=q
            break
    if c8_line:
        break

# Independent narrow equality check against canonical repair commit worktree.
repair_files={
    "supervisor":"control/codex_supervisor/supervisor.py",
    "candidate_reporting":"control/hourly/candidate_reporting.py",
}
repair_diff=[]
for label,rel in repair_files.items():
    a=root/rel
    b=prod/rel
    if (not a.is_file()) or (not b.is_file()) or b.is_symlink() or sha(a)!=sha(b):
        repair_diff.append(label)

mapping={
"candidate_dispatch.py_sha256":"control/codex_supervisor/candidate_dispatch.py",
"candidate_policy_sha256":"control/hourly/candidate_queue.py",
"evidence_wake.py_sha256":"control/codex_supervisor/evidence_wake.py",
"build_wake.py_sha256":"control/codex_supervisor/build_wake.py",
"model_quality_gate.py_sha256":"control/codex_supervisor/model_quality_gate.py",
"astra_review_wake.py_sha256":"control/codex_supervisor/astra_review_wake.py",
"measurement_wake.py_sha256":"control/codex_supervisor/measurement_wake.py",
"supervisor_sha256":"control/codex_supervisor/supervisor.py",
"astra_autonomous_review.py_sha256":"control/codex_supervisor/astra_autonomous_review.py",
}
cfg=read_json(prod/"knowledge/codex_runtime/CONFIG.json") or {}
bad_pins=[]
for key,rel in mapping.items():
    p=prod/rel
    if (not p.is_file()) or p.is_symlink() or cfg.get(key)!=sha(p):
        bad_pins.append(key.replace(".py_sha256","").replace("_sha256",""))

result={
    "prior_final":states["DEV-PRED-REQUESTED-REPAIRS-FINAL-ACCEPT-20261005"],
    "prior_targeted":states["DEV-PRED-REPAIRS-TARGETED-VERIFY-R2-20261005"],
    "prior_c8":states[C8],
    "c8_queue":c8_queue,
    "c8_payload":json.loads(c8_line) if c8_line else None,
    "current_repair_diff":repair_diff,
    "current_bad_pins":bad_pins,
}
print("REPAIR_RECOVER "+json.dumps(result,separators=(",",":"),sort_keys=True),flush=True)

# PASS is deliberately narrow: requested repaired production modules equal canonical repair commit,
# all nine runtime pins are internally exact, and the prior targeted verification passed.
ok=(not repair_diff and not bad_pins and states["DEV-PRED-REPAIRS-TARGETED-VERIFY-R2-20261005"].get("status")=="PASS")
raise SystemExit(0 if ok else 1)
